"""Builds BENCHMARK_REPORT.md from results/*.json (all numbers computed here)."""
import json, collections, pathlib
from evaluate import RULES  # noqa  (re-runs evaluation print; harmless)
HERE = pathlib.Path(__file__).parent
ev = json.load(open(HERE / "results/eval.json"))
REPOS = list(ev)
inv = collections.defaultdict(set)
for cat, rs in RULES.items():
    for r in rs: inv[r].add(cat)
def cat_of(f):
    if f["tool"] == "gitleaks": return "hardcoded-secret"
    c = sorted(inv.get(f["rule_id"], []))
    return c[0] if c else "other:" + f["rule_id"]
LAB = {"vulnerable-dependency-n/a": 0}
# real-repo sample labels (index in results/real_sample.json -> label, reason) -- from manual inspection of evidence
REAL = {
 "itsdangerous": [("debatable","virtualenv advisory is real but dev-tooling transitive in uv.lock, rated high"),
   ("debatable","broad except that re-raises BadPayload from e; legitimate pattern"),
   ("FP","@overload stub signatures flagged as duplicated code"),
   ("debatable","87 lines incl. long docstring"),
   ("debatable","8-param __init__ of public API; low severity"),
   ("TP","except Exception: pass in timestamp parsing really swallows"),
   ("debatable","sha1 is the default digest for HMAC key derivation, not password hashing"),
   ("FP","docs/conf.py is not a module needing tests"),
   ("debatable","uv 0.7.8 advisories real but dev tooling in uv.lock, rated critical"),
   ("debatable","broad except that re-raises")],
 "full-stack-fastapi-template": [("debatable","POST /private/users is the template's local-only private router, intentionally unauthenticated"),
   ("FP","target frontend/src/components/ui/dialog.tsx exists; tsconfig is in frontend/ and uses /* */ comments"),
   ("TP","minimatch advisory per OSV (transitive, dev tooling)"),
   ("debatable","generated *.gen.ts client code"),
   ("FP","identical import lists across two route files flagged as duplicate code"),
   ("debatable","generated code, empty catch carries '// noop' comment"),
   ("TP","complexity 32 is real (generated code)"),
   ("debatable","738-line vendored shadcn sidebar"),
   ("TP","DataTable really is 155 lines"),
   ("FP","leading-underscore private helper is a conventional name")]}
samp = json.load(open(HERE / "results/real_sample.json"))
L = []; w = L.append
w("# AI Engineering Auditor - ground-truth detection benchmark\n")
w("Generated by `make_report.py` from `results/*.json`; every number below was computed by a script in this directory. Narrative sections were written after reading the computed output.\n")
w("## 1. Methodology\n")
w("""- Analyzer: `run_analysis(Path(repo), Settings(offline=False))` from ROOT/backend (semgrep + gitleaks + OSV-Scanner + Trivy all status `ok` in every reported run; OSV used live network, sending package names/versions only). ROOT was not modified. Benchmark code was never executed, only read by the analyzer.
- Ground truth: planted issues carry an inline marker `GT:<id>|<category>|<cwe>|<expect>` on the line before the vulnerable line; `SAFE:<id>|<category>` marks look-alikes that must not be flagged. `build_ground_truth.py` extracts them into `ground_truth/<repo>.json` (file, line, category, cwe, expected_detect). Items not detectable by design (prototype pollution, NoSQL injection) are recorded with `expected_detect=false`.
- Match rule (`evaluate.py`): same file, |line diff| <= 3 (<= 1 for unresolved-import), and the finding's rule belongs to the category's rule set (`RULES` in evaluate.py; e.g. any gitleaks finding for a hardcoded-secret). Graph/duplicate/no-tests items ignore line. One finding can satisfy only one planted item.
- Every unmatched finding was labelled by hand in `labels.json` (TP-unplanted / debatable / FP, with reason); a finding firing on a SAFE look-alike is auto-labelled FP. Zero findings remain unlabeled.
- Precision is shown at three levels: strict = planted TP / all findings in that category; adjusted = (planted + true-but-unplanted) / all; and the range with debatable counted as wrong (low) or right (high). Recall = detected / planted-with-expected_detect=true.
- Limitations: all repos are small and synthetic, written by one author (me), one variant per issue type, so recall numbers measure these variants only; 'true-but-unplanted' dependency advisories were not independently verified beyond OSV's output; the real-repo samples are 10 findings each, hand-labelled by me, so they are indicative only.
""")
w("## 2. Repos and planted issues\n")
for r in REPOS:
    g = json.load(open(HERE / f"ground_truth/{r}.json"))
    w(f"### {r}: {len(g['planted'])} planted ({sum(p['expected_detect'] for p in g['planted'])} expected detectable), {len(g['safe_lookalikes'])} safe look-alikes\n")
    if g["planted"]:
        w("Planted: " + "; ".join(f"`{p['id']}` ({p['category']}, {p['file']}:{p['line']}{'' if p['expected_detect'] else ', known gap'})" for p in g["planted"]) + "\n")
    if g["safe_lookalikes"]:
        w("Safe look-alikes: " + ", ".join(f"`{s['id']}`" for s in g["safe_lookalikes"]) + "\n")
    if r == "clean_repo": w("No intentional issues; Python package with pytest tests and a TS module with vitest tests; no dependencies in pyproject.toml; package.json devDependencies only (no lockfile).\n")
w("## 3. Results per repo\n")
w("| repo | planted (expected) | detected | recall | findings | planted-matched | TP-unplanted | debatable | FP | score | grade |\n|---|---|---|---|---|---|---|---|---|---|---|")
TOT = collections.Counter()
for r in REPOS:
    o = ev[r]; exp = [x for x in o["rows"] if x["gt"]["expected_detect"]]; det = sum(x["detected"] for x in exp)
    lab = collections.Counter(u["label"] for u in o["unmatched"])
    matched = sum(x["detected"] for x in o["rows"])
    rec = f"{det}/{len(exp)} = {det/len(exp):.0%}" if exp else "n/a"
    w(f"| {r} | {len(exp)} | {det} | {rec} | {o['n_findings']} | {matched} | {lab['TP-unplanted']} | {lab['debatable']} | {lab['FP']} | {o['scores']['overall']} | {o['scores']['grade']} |")
    TOT.update(exp=len(exp), det=det, fnd=o["n_findings"], matched=matched, tpu=lab["TP-unplanted"], deb=lab["debatable"], fp=lab["FP"])
w(f"| **all synthetic** | {TOT['exp']} | {TOT['det']} | {TOT['det']}/{TOT['exp']} = {TOT['det']/TOT['exp']:.1%} | {TOT['fnd']} | {TOT['matched']} | {TOT['tpu']} | {TOT['deb']} | {TOT['fp']} | | |\n")
w("(`planted-matched` counts matched findings including known-gap items if they were ever matched; all known-gap items were missed.)\n")
# per category
w("## 4. Precision / recall per category (synthetic repos pooled)\n")
cats = collections.OrderedDict()
def C(c): return cats.setdefault(c, collections.Counter())
for r in REPOS:
    o = ev[r]
    for x in o["rows"]:
        c = x["gt"]["category"]
        if x["gt"]["expected_detect"]:
            C(c)["planted"] += 1; C(c)["det"] += x["detected"]
            if x["detected"]: C(c)["F"] += 1; C(c)["tp"] += 1
        else:
            C(c)["gap"] += 1; C(c)["gapdet"] += x["detected"]
    for u in o["unmatched"]:
        f = u["finding"]; c = cat_of({"tool": f["tool"], "rule_id": f["rule_id"]})
        C(c)["F"] += 1; C(c)[{"TP-unplanted": "tpu", "debatable": "deb", "FP": "fp"}[u["label"]]] += 1
w("| category | planted | detected | recall | findings (F) | planted TP | TP-unplanted | debatable | FP | strict precision | adjusted precision | adj. range (deb wrong..right) |\n|---|---|---|---|---|---|---|---|---|---|---|---|")
def pct(a, b): return f"{a}/{b} = {a/b:.0%}" if b else "n/a"
for c, k in cats.items():
    if c.startswith("other:") and not k["F"]: continue
    F = k["F"]; adj = k["tp"] + k["tpu"]
    rng = f"{adj/F:.0%}..{(adj+k['deb'])/F:.0%}" if F else "n/a"
    rc = pct(k["det"], k["planted"]) if k["planted"] else (f"0/{k['gap']} (known gap)" if k["gap"] else "n/a")
    w(f"| {c} | {k['planted']} | {k['det']} | {rc} | {F} | {k['tp']} | {k['tpu']} | {k['deb']} | {k['fp']} | {pct(k['tp'], F)} | {pct(adj, F)} | {rng} |")
sec = [c for c in cats if not c.startswith("other:") and c not in {"circular-dependency","unresolved-import","coupling-hub","large-class","high-complexity","deep-nesting","long-function","duplicate-code","bare-except","swallowed-exception","empty-catch","many-parameters","no-tests"}]
arch = [c for c in cats if c in {"circular-dependency","unresolved-import","coupling-hub","large-class","high-complexity","deep-nesting","long-function","duplicate-code","bare-except","swallowed-exception","empty-catch","many-parameters","no-tests"}]
def agg(cs, extra_other=False):
    t = collections.Counter()
    for c in cs: t.update(cats[c])
    if extra_other:
        for c in cats:
            if c.startswith("other:"): t.update({k: v for k, v in cats[c].items() if k in ("F","tpu","deb","fp")})
    return t
for name, cs, eo in (("Security (vulns + secrets)", sec, False), ("Architecture/quality/reliability", arch, False)):
    t = agg(cs, eo); adj = t["tp"] + t["tpu"]
    w(f"\n**{name}, expected-detectable only:** recall {pct(t['det'], t['planted'])}; precision strict {pct(t['tp'], t['F'])}, adjusted {pct(adj, t['F'])}, range {adj/t['F']:.0%}..{(adj+t['deb'])/t['F']:.0%} (F={t['F']}, TP-unplanted={t['tpu']}, debatable={t['deb']}, FP={t['fp']}).")
oth = collections.Counter()
for c, k in cats.items():
    if c.startswith("other:"): oth.update({a: b for a, b in k.items() if a in ("F","tpu","deb","fp")}); 
w(f"\nFindings from rules outside every planted category (dependency advisories, select-star, mixed-http-data, naming): F={oth['F']}, TP-unplanted={oth['tpu']}, debatable={oth['deb']}, FP={oth['fp']}.\n")
for c, k in cats.items():
    if c.startswith("other:"): w(f"- `{c[6:]}`: F={k['F']}, TP-unplanted={k['tpu']}, debatable={k['deb']}, FP={k['fp']}")
w("\nOverall (all planted categories, expected-detectable): recall %s; planted TPs %d of %d total findings across the 5 synthetic repos => strict precision %s, adjusted precision %s, adjusted range %.0f%%..%.0f%%.\n" % (
  pct(TOT["det"], TOT["exp"]), TOT["matched"], TOT["fnd"], pct(TOT["matched"], TOT["fnd"]), pct(TOT["matched"] + TOT["tpu"], TOT["fnd"]),
  100*(TOT["matched"]+TOT["tpu"])/TOT["fnd"], 100*(TOT["matched"]+TOT["tpu"]+TOT["deb"])/TOT["fnd"]))
# FN list
CAUSE = {
 "sqli_plus": "rule pattern gap: concat patterns only match `\"...\" + $X` (2 operands); `\"...\" + x + \"'\"` (3 operands, the usual quoted form) is a nested BinOp and is not matched (confirmed by probe_sqli_concat: 2-operand detected, 3-operand missed, direct and via intermediate var)",
 "sqli_intermediate": "rule pattern gap: same 3-operand concat gap, via intermediate variable (probe_sqli_concat case d)",
 "sqli_concat": "rule pattern gap: JS `pool.query(\"...\" + req.query.name + \"'\")` 3-operand concat not matched",
 "path_readfile": "rule pattern gap: js-path-traversal covers sendFile-style sinks but not fs.readFileSync(\"/data/\" + req.query.f)",
 "proto_pollution_merge": "by-design/no rule (known gap)", "proto_pollution_assign": "by-design/no rule (known gap)", "nosql_injection": "by-design/no rule (known gap)",
 "noauth_delete": "heuristic gap: design.GLOBAL_AUTH_RE treats any `.use(...session...)` in the file as global auth; the file's `app.use(require(\"express-session\")...)` suppresses api-unauthenticated-mutation for every route in server.js",
 "insecure_cookie": "rule pattern gap: js-insecure-cookie only matches `res.cookie(n, v, {secure:false|httpOnly:false})`, not express-session `cookie: {...}` options",
 "py_dburl": "rule missing: no semgrep rule and gitleaks default ruleset has no credentialed-DB-URL rule",
 "py_hub": "threshold/by-design: coupling-hub needs fan-in >= max(8,25%) AND fan-out >= 6; a pure fan-in module (14 importers, 0 imports) is never reported (arguably correct for a stable utility; my planted hub was fan-in only)",
 "ts_broken_alias": "logic gap in graph._resolve_js: an alias prefix configured in tsconfig `paths` (here `@lib/`) whose target is missing returns `internal=False` unless the prefix starts with `@/`, `~/` or `#`, so it is silently treated as an npm package. probe_alias_root (tsconfig at repo root) reproduces it, so it is not only the nested-tsconfig issue (tsconfig is also only read from the repo root)",
}
w("## 5. False negatives\n")
w("| repo | id | category | location | expected | likely cause |\n|---|---|---|---|---|---|")
for r in REPOS:
    for x in ev[r]["rows"]:
        if not x["detected"]:
            g = x["gt"]; w(f"| {r} | {g['id']} | {g['category']} | {g['file']}:{g['line']} | {'detect' if g['expected_detect'] else 'known gap'} | {CAUSE.get(g['id'], '?')} |")
w("")
# FP list
w("## 6. Unmatched findings (FP / debatable / true-but-unplanted) on synthetic repos\n")
w("| repo | location | rule | sev | label | reason |\n|---|---|---|---|---|---|")
for r in REPOS:
    for u in ev[r]["unmatched"]:
        f = u["finding"]
        if u["label"] == "TP-unplanted" and f["rule_id"] == "vulnerable-dependency": continue
        w(f"| {r} | {f['file']}:{f['line']} | {f['rule_id']} | {f['severity']} | {u['label']} | {u['reason']} |")
dep = [(r, u) for r in REPOS for u in ev[r]["unmatched"] if u["finding"]["rule_id"] == "vulnerable-dependency"]
w(f"\n{len(dep)} `vulnerable-dependency` findings (vuln_py/requirements.txt) labelled TP-unplanted: " + "; ".join(u["finding"]["title"] + f" [{u['finding']['severity']}]" for r, u in dep) + ".\n")
safe = [(r, u) for r in REPOS for u in ev[r]["unmatched"] if u["safe_hit"]]
nsafe = sum(len(json.load(open(HERE / f"ground_truth/{r}.json"))["safe_lookalikes"]) for r in REPOS)
w(f"**Safe look-alikes:** {nsafe} planted; findings landing on one: {len(safe)} ({', '.join(u['safe_hit'][0] + ' via ' + u['finding']['rule_id'] for r, u in safe) or 'none'}). The cluster of safe look-alike code (parameterised SQL, list-arg subprocess, safe_load, literal_eval, verify=True, constant eval, secure_filename, Depends(current_user), DOMPurify, textContent, execFile, jwt.verify, crypto.randomBytes, md5 usedforsecurity=False, env-sourced keys, .env.example placeholders, SHA256/UUID/git-sha/base64 constants) produced no security-rule false positives on the marked lines. One look-alike-adjacent FP exists that the line-based safe check missed (marker is inside the function, finding is on the decorator): `api-unauthenticated-mutation` on POST /safe/yaml (labelled FP above), so the true count of findings on safe look-alike routes is 1. Note: `secure_filename` + send_file and `path.basename` + sendFile were not flagged, but the path-traversal rules require request data on the same expression, so this is partly by construction.\n")
# severity sanity
w("## 7. Severity sanity, duplicates\n")
w("Gitleaks findings in secrets_repo (severity by file):\n")
sr = json.load(open(HERE / "results/secrets_repo.json"))
w("| file | line | rule | severity | conf |\n|---|---|---|---|---|")
for f in sorted(sr["findings"], key=lambda f: (f["file"] or "", f["line"] or 0)):
    if f["tool"] == "gitleaks": w(f"| {f['file']} | {f['line']} | {f['rule_id']} | {f['severity']} | {f['confidence']} |")
w("""
- Fixture/test-looking files are down-rated to `low` (README_fixture_secret.py, fixtures/sample_data.json): sensible. `.env.example` placeholders and the SHA256/UUID/git-sha/base64 constants were not flagged at all (0 secret FPs).
- Inconsistent: the same class of secret is `critical` in YAML/py/js but `high` in `.env` (aws-access-token and the AWS secret); a real AWS key pair in `.env` is arguably the most critical item.
- vuln_js `.env.local` NEXT_PUBLIC secret: reported by gitleaks as generic-api-key `high`; the semgrep `js-secret-exposed-to-browser` rule matched the code use but not the .env definition.
- Dependency advisories: severity is the max advisory; e.g. transitive certifi and anyio rated `critical`, itsdangerous dev tooling (uv, virtualenv in uv.lock) rated critical/high although they are not runtime dependencies of the library (analyzer has a runtime/dev classifier, but severity still came out high/critical there).
""")
dups = []
for r in REPOS:
    d = json.load(open(HERE / f"results/{r}.json"))
    by = collections.defaultdict(list)
    for f in d["findings"]:
        if f["line"]: by[(f["file"], f["line"])].append(f)
    for k, v in by.items():
        if len(v) > 1: dups.append((r, k, [f"{f['tool']}/{f['rule_id']}" for f in v]))
w("Same file+line reported by more than one tool/rule (computed):\n")
for r, k, v in dups: w(f"- {r} {k[0]}:{k[1]}: {', '.join(v)}")
w("""
Reading: these are different concerns (injection plus select-star; XSS plus eval), not true duplicates; no case of the same issue reported twice by two scanners appeared. Related double counting: `res.send(String(eval(...)))` yields both js-eval and js-reflected-xss-express, and `.env` reports two secrets on adjacent lines (that is correct, two secrets). Since SC-02, findings in the same category on the same file and line are scored once (the most severe); both are still listed. Pairs above in different categories (security vs code_quality) are not merged.
""")
# scores
w("## 8. Scores\n")
w("| repo | overall | grade | uncapped | caps | same-line duplicates scored once | security | reliability | architecture | code_quality | maintainability |\n|---|---|---|---|---|---|---|---|---|---|---|")
allr = REPOS + ["itsdangerous", "full-stack-fastapi-template"]
_na = lambda v: "N/A" if v is None else v  # noqa: E731
for r in allr:
    s = json.load(open(HERE / f"results/{r}.json"))["scores"]; c = s["categories"]
    w(f"| {r} | {_na(s['overall'])} | {s['grade']} | {_na(s.get('uncapped_overall', s['overall']))} | {', '.join(s.get('caps', [])) or '-'} | {s.get('merged_duplicates', '-')} | "
      + " | ".join(str(_na(c[k])) for k in ("security", "reliability", "architecture", "code_quality", "maintainability")) + " |")
w("""
Ordering (computed above): clean_repo 100 > itsdangerous > arch_repo > vuln_js > secrets_repo > full-stack-fastapi-template > vuln_py. Clean scores highest and the security-heavy repos score low in the *security* column (vuln_py 1.9, secrets 6.8, vuln_js 12.0), so the security category behaves sensibly. Since DET-01, the three-operand SQL concatenations are detected, which lowers vuln_py (65.4 → 65.3) and vuln_js (70.2 → 69.4). Effect of the SC-01/SC-02 fixes on these repos (before → after, same findings): vuln_js 69.7 D → 70.2 C (its eval + reflected-XSS pair on one line now counts once: security 12.8 → 14.7); full-stack-fastapi-template 68.2 → 68.3 (two complexity + deep-nesting pairs); probe_sqli_concat 82.1 B → 79.9 C (critical cap); all others unchanged. All four scanners ran on every repo, so no result is marked incomplete and no category is N/A. Weaknesses:
- The overall score still compresses: secrets_repo (seven critical-severity secret findings; security 6.8) gets 68.4 / D, and vuln_py (five critical SQL injections plus many high findings; security 2.1) gets 65.3 / D, because the other four categories stay near 82-100 and security has weight 0.30. The critical cap (79.9) only bites when the weighted mean is above it, so it does not separate these from arch_repo. This is DET-15 / SC-04 territory, not addressed here.
- arch_repo has no security findings and no tests but 19 structural issues and scores 79.2 / C, above vuln_js (69.4).
- itsdangerous keeps 81.4 / B: its critical dependency advisories are transitive (confidence medium, DET-11), and the cap only applies to high-confidence criticals.
- clean_repo scores 100.0 with zero findings: no false positives (n=1 small repo; says little about larger clean repos).
""")
# real
